PREFIX ref: <http://swip.tslab.example/ref#>
SELECT ?z ?lbl WHERE {
  ?z rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl,"Core"))
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?pt ?pcl ?ts WHERE {
  VALUES ?z { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01> }
  ?z brick:hasPoint ?pt .
  ?pt rdf:type ?pttype .
  ?pt brick:isPointOf ?loc .
  ?pt ref:hasTimeseriesId ?ts .
  BIND(str(?pttype) AS ?pcl)
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?pt ?pttype ?ts ?loc WHERE {
  VALUES ?z { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z01> }
  ?z brick:hasPoint ?pt .
  ?pt rdf:type ?pttype .
  OPTIONAL { ?pt brick:isPointOf ?loc . }
  OPTIONAL { ?pt ref:hasTimeseriesId ?ts . }
}

